class Solution:
    def minOperations(self, nums: List[int], k: int) -> int:
        best = float('inf')
        for i in range(len(nums) - k + 1):
            w = sorted(nums[i:i + k])
            m = w[k // 2]
            best = min(best, sum(abs(x - m) for x in w))
        return best

