import heapq
from collections import defaultdict

class Solution:
    def minOperations(self, nums: List[int], k: int) -> int:
        lower, upper = [], []
        delayed = defaultdict(int)
        st = {'sumL': 0, 'sumU': 0, 'szL': 0, 'szU': 0}

        def prune():
            while lower and delayed[-lower[0]]:
                delayed[-lower[0]] -= 1
                heapq.heappop(lower)
            while upper and delayed[upper[0]]:
                delayed[upper[0]] -= 1
                heapq.heappop(upper)

        def rebalance():
            prune()
            while st['szL'] > st['szU'] + 1:
                v = -heapq.heappop(lower)
                heapq.heappush(upper, v)
                st['sumL'] -= v; st['sumU'] += v; st['szL'] -= 1; st['szU'] += 1
                prune()
            while st['szU'] > st['szL']:
                v = heapq.heappop(upper)
                heapq.heappush(lower, -v)
                st['sumU'] -= v; st['sumL'] += v; st['szU'] -= 1; st['szL'] += 1
                prune()

        def add(x):
            prune()
            if not lower or x <= -lower[0]:
                heapq.heappush(lower, -x); st['sumL'] += x; st['szL'] += 1
            else:
                heapq.heappush(upper, x); st['sumU'] += x; st['szU'] += 1
            rebalance()

        def remove(x):
            prune()
            if x <= -lower[0]:
                st['sumL'] -= x; st['szL'] -= 1
            else:
                st['sumU'] -= x; st['szU'] -= 1
            delayed[x] += 1
            rebalance()

        def cost():
            prune()
            m = -lower[0]
            return m * st['szL'] - st['sumL'] + st['sumU'] - m * st['szU']

        for i in range(k):
            add(nums[i])
        best = cost()
        for i in range(k, len(nums)):
            add(nums[i]); remove(nums[i - k])
            best = min(best, cost())
        return best

