class Solution {
public:
    long long minOperations(vector<int>& nums, int k) {
        multiset<int> lo, hi;
        long long sumL = 0, sumU = 0;
        auto rebalance = [&]() {
            while (lo.size() > hi.size() + 1) {
                auto it = prev(lo.end());
                sumL -= *it; sumU += *it;
                hi.insert(*it); lo.erase(it);
            }
            while (hi.size() > lo.size()) {
                auto it = hi.begin();
                sumU -= *it; sumL += *it;
                lo.insert(*it); hi.erase(it);
            }
        };
        auto add = [&](int x) {
            if (lo.empty() || x <= *lo.rbegin()) { lo.insert(x); sumL += x; }
            else { hi.insert(x); sumU += x; }
            rebalance();
        };
        auto remove = [&](int x) {
            if (x <= *lo.rbegin()) { lo.erase(lo.find(x)); sumL -= x; }
            else { hi.erase(hi.find(x)); sumU -= x; }
            rebalance();
        };
        for (int i = 0; i < k; i++) add(nums[i]);
        long long best = LLONG_MAX;
        for (int i = k; ; i++) {
            long long m = *lo.rbegin();
            best = min(best, m * (long long)lo.size() - sumL + sumU - m * (long long)hi.size());
            if (i >= (int)nums.size()) break;
            add(nums[i]); remove(nums[i - k]);
        }
        return best;
    }
};

