class Solution {
    public long minOperations(int[] nums, int k) {
        PriorityQueue<Integer> lower = new PriorityQueue<>(Collections.reverseOrder());
        PriorityQueue<Integer> upper = new PriorityQueue<>();
        Map<Integer, Integer> delayed = new HashMap<>();
        long[] sum = new long[2];
        int[] sz = new int[2];
        Runnable prune = () -> {
            while (!lower.isEmpty() && delayed.getOrDefault(-lower.peek(), 0) > 0) {
                delayed.merge(-lower.peek(), -1, Integer::sum);
                lower.poll();
            }
            while (!upper.isEmpty() && delayed.getOrDefault(upper.peek(), 0) > 0) {
                delayed.merge(upper.peek(), -1, Integer::sum);
                upper.poll();
            }
        };
        Runnable rebalance = () -> {
            prune.run();
            while (sz[0] > sz[1] + 1) {
                int v = -lower.poll();
                upper.add(v);
                sum[0] -= v; sum[1] += v; sz[0]--; sz[1]++;
                prune.run();
            }
            while (sz[1] > sz[0]) {
                int v = upper.poll();
                lower.add(-v);
                sum[1] -= v; sum[0] += v; sz[1]--; sz[0]++;
                prune.run();
            }
        };
        java.util.function.IntConsumer add = x -> {
            prune.run();
            if (lower.isEmpty() || x <= -lower.peek()) { lower.add(-x); sum[0] += x; sz[0]++; }
            else { upper.add(x); sum[1] += x; sz[1]++; }
            rebalance.run();
        };
        java.util.function.IntConsumer remove = x -> {
            prune.run();
            if (x <= -lower.peek()) { sum[0] -= x; sz[0]--; }
            else { sum[1] -= x; sz[1]--; }
            delayed.merge(x, 1, Integer::sum);
            rebalance.run();
        };
        for (int i = 0; i < k; i++) add.accept(nums[i]);
        long best = Long.MAX_VALUE;
        for (int i = k; ; i++) {
            prune.run();
            long m = -lower.peek();
            best = Math.min(best, m * sz[0] - sum[0] + sum[1] - m * sz[1]);
            if (i >= nums.length) break;
            add.accept(nums[i]);
            remove.accept(nums[i - k]);
        }
        return best;
    }
}

