var minOperations = function(nums, k) {
    class Heap {
        constructor(cmp) { this.a = []; this.cmp = cmp; }
        get top() { return this.a[0]; }
        push(x) {
            const a = this.a; a.push(x);
            let i = a.length - 1;
            while (i > 0) {
                const p = (i - 1) >> 1;
                if (this.cmp(a[i], a[p])) { [a[i], a[p]] = [a[p], a[i]]; i = p; } else break;
            }
        }
        pop() {
            const a = this.a, t = a[0], l = a.pop();
            if (a.length) {
                a[0] = l; let i = 0;
                for (;;) {
                    let s = i, L = 2 * i + 1, R = L + 1;
                    if (L < a.length && this.cmp(a[L], a[s])) s = L;
                    if (R < a.length && this.cmp(a[R], a[s])) s = R;
                    if (s === i) break;
                    [a[i], a[s]] = [a[s], a[i]]; i = s;
                }
            }
            return t;
        }
    }
    const lower = new Heap((a, b) => a > b), upper = new Heap((a, b) => a < b);
    const delayed = new Map();
    let sumL = 0, sumU = 0, szL = 0, szU = 0;
    const prune = () => {
        while (lower.a.length && (delayed.get(-lower.top) || 0) > 0) {
            delayed.set(-lower.top, delayed.get(-lower.top) - 1); lower.pop();
        }
        while (upper.a.length && (delayed.get(upper.top) || 0) > 0) {
            delayed.set(upper.top, delayed.get(upper.top) - 1); upper.pop();
        }
    };
    const rebalance = () => {
        prune();
        while (szL > szU + 1) {
            const v = -lower.pop(); upper.push(v);
            sumL -= v; sumU += v; szL--; szU++; prune();
        }
        while (szU > szL) {
            const v = upper.pop(); lower.push(-v);
            sumU -= v; sumL += v; szU--; szL++; prune();
        }
    };
    const add = (x) => {
        prune();
        if (!lower.a.length || x <= -lower.top) { lower.push(-x); sumL += x; szL++; }
        else { upper.push(x); sumU += x; szU++; }
        rebalance();
    };
    const remove = (x) => {
        prune();
        if (x <= -lower.top) { sumL -= x; szL--; }
        else { sumU -= x; szU--; }
        delayed.set(x, (delayed.get(x) || 0) + 1);
        rebalance();
    };
    for (let i = 0; i < k; i++) add(nums[i]);
    let best = Infinity;
    for (let i = k; ; i++) {
        prune();
        const m = -lower.top;
        best = Math.min(best, m * szL - sumL + sumU - m * szU);
        if (i >= nums.length) break;
        add(nums[i]); remove(nums[i - k]);
    }
    return best;
};
